    IF to_regclass('employee.record_change_requests') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('employee.record_change_requests') AND conname = 'ck_record_change_requests_field_path_required__required') THEN
        IF EXISTS (SELECT 1 FROM employee.record_change_requests WHERE NOT ((field_path IS NOT NULL AND btrim(field_path::text) <> ''))) THEN
            RAISE NOTICE 'ck_record_change_requests_field_path_required__required not added: stored rows of employee.record_change_requests break it';
        ELSE
            ALTER TABLE employee.record_change_requests ADD CONSTRAINT ck_record_change_requests_field_path_required__required CHECK ((field_path IS NOT NULL AND btrim(field_path::text) <> ''));
        END IF;
    END IF;
EXCEPTION WHEN undefined_column THEN
    RAISE NOTICE 'ck_record_change_requests_field_path_required__required not added: employee.record_change_requests lacks a column it reads';
END $$;

